<div class="app-shell">
    <header class="topbar"><a class="brand" href="<?= base_url('dashboard') ?>"><span class="brand-mark"><i class="bi bi-lightning-charge-fill"></i></span><span>Puihaha<br><small>Electric Company</small></span></a><div class="topbar-actions"><span class="welcome"><i class="bi bi-person-circle"></i> <?= esc($username) ?></span><form action="<?= base_url('logout') ?>" method="post"><?= csrf_field() ?><button class="logout" type="submit"><i class="bi bi-box-arrow-right"></i> Log out</button></form></div></header>
    <main class="content">
        <div class="page-heading"><div><p class="eyebrow">CUSTOMER MANAGEMENT</p><h1>Account Dashboard</h1><p class="subheading">Manage Puihaha Electric Company customer accounts.</p></div><a class="button primary" href="<?= base_url('account/create') ?>"><i class="bi bi-plus-lg"></i> Add customer</a></div>
        <?php if ($message = session()->getFlashdata('success')): ?><div class="notice success"><i class="bi bi-check-circle-fill"></i><?= esc($message) ?></div><?php endif; ?>
        <?php if ($message = session()->getFlashdata('error')): ?><div class="notice error"><i class="bi bi-exclamation-circle-fill"></i><?= esc($message) ?></div><?php endif; ?>
