        <section class="panel"><div class="panel-head"><div><h2>Customer accounts</h2><p>View, edit, or remove registered accounts.</p></div><span class="record-count"><i class="bi bi-database"></i> <?= esc($total_accounts) ?> records</span></div>
            <form class="filters" method="get" action="<?= base_url('dashboard') ?>"><label class="search-box"><i class="bi bi-search"></i><input name="search" value="<?= esc($search_keyword) ?>" placeholder="Search accounts, names, email..." aria-label="Search accounts"></label><select name="status" aria-label="Filter by status"><option value="">All statuses</option><option value="active" <?= $filter_status === 'active' ? 'selected' : '' ?>>Active</option><option value="inactive" <?= $filter_status === 'inactive' ? 'selected' : '' ?>>Inactive</option><option value="suspended" <?= $filter_status === 'suspended' ? 'selected' : '' ?>>Suspended</option></select><select name="type" aria-label="Filter by connection type"><option value="">All types</option><option value="residential" <?= $filter_type === 'residential' ? 'selected' : '' ?>>Residential</option><option value="commercial" <?= $filter_type === 'commercial' ? 'selected' : '' ?>>Commercial</option><option value="industrial" <?= $filter_type === 'industrial' ? 'selected' : '' ?>>Industrial</option></select><button class="button dark" type="submit">Filter</button><a class="clear-link" href="<?= base_url('dashboard') ?>">Clear</a></form>
            <div class="table-wrap"><table><thead><tr><th>Account number</th><th>Customer</th><th>Contact</th><th>Meter</th><th>Type</th><th>Status</th><th class="actions-col">Actions</th></tr></thead><tbody><?php if (empty($accounts)): ?><tr><td class="empty" colspan="7">No customer accounts found.</td></tr><?php else: foreach ($accounts as $account): ?><tr><td><strong><?= esc($account['account_number']) ?></strong><small><?= esc($account['address']) ?></small></td><td><?= esc($account['customer_name']) ?></td><td><span><?= esc($account['email'] ?: '—') ?></span><small><?= esc($account['phone'] ?: 'No phone') ?></small></td><td><?= esc($account['meter_number'] ?: '—') ?></td><td><span class="type-pill"><?= esc(ucfirst($account['connection_type'])) ?></span></td><td><span class="status <?= esc($account['status']) ?>"><i class="bi bi-circle-fill"></i><?= esc(ucfirst($account['status'])) ?></span></td><td class="row-actions"><a title="View" href="<?= base_url('account/' . $account['id']) ?>"><i class="bi bi-eye"></i></a><a title="Edit" href="<?= base_url('account/' . $account['id'] . '/edit') ?>"><i class="bi bi-pencil-square"></i></a><form action="<?= base_url('account/' . $account['id'] . '/delete') ?>" method="post" onsubmit="return confirm('Delete this customer account?')"><?= csrf_field() ?><button title="Delete" type="submit"><i class="bi bi-trash3"></i></button></form></td></tr><?php endforeach; endif; ?></tbody></table></div>
            <?php if ($pager && $pager->getPageCount() > 1): ?><div class="pagination"><?= $pager->links() ?></div><?php endif; ?>
